import { useEffect, useState } from "react";
import { useSearchParams } from "react-router-dom";
import api from "../api";

function Chat() {
  const userId = Number(localStorage.getItem("userId"));
  const [searchParams] = useSearchParams();

  // coming from feed → /chat?user=5
  const initialUser = searchParams.get("user")
    ? Number(searchParams.get("user"))
    : null;

  const [messages, setMessages] = useState([]);
  const [contacts, setContacts] = useState([]);
  const [activeUser, setActiveUser] = useState(initialUser);
  const [text, setText] = useState("");

  /* ================= FETCH ALL CHATS ================= */
  useEffect(() => {
    if (!userId) return;

    api.get(`/chat/${userId}`).then((res) => {
      const data = res.data || [];
      setMessages(data);

      // build contacts list
      const map = {};
      data.forEach((m) => {
        const other =
          m.sender_id === userId ? m.receiver_id : m.sender_id;
        if (other) map[other] = true;
      });

      setContacts(Object.keys(map).map(Number));
    });
  }, [userId]);

  /* ================= SEND MESSAGE ================= */
  const sendMessage = () => {
    if (!text.trim() || !activeUser) return;

    api.post("/chat", {
      sender_id: userId,
      receiver_id: activeUser,
      batch_id: null,
      message_text: text,
    }).then(() => {
      setMessages((prev) => [
        ...prev,
        {
          sender_id: userId,
          receiver_id: activeUser,
          message_text: text,
        },
      ]);

      // add to contacts if first message
      if (!contacts.includes(activeUser)) {
        setContacts((prev) => [...prev, activeUser]);
      }

      setText("");
    });
  };

  /* ================= FILTER ACTIVE CHAT ================= */
  const activeMessages = messages.filter(
    (m) =>
      (m.sender_id === userId && m.receiver_id === activeUser) ||
      (m.sender_id === activeUser && m.receiver_id === userId)
  );

  return (
    <div className="chat-layout">
      {/* ===== SIDEBAR ===== */}
      <aside className="chat-sidebar glass">
        <h3>Chats</h3>

        {contacts.length === 0 && (
          <p className="empty-text">No conversations yet</p>
        )}

        {contacts.map((id) => (
          <div
            key={id}
            className={`chat-contact ${
              activeUser === id ? "active" : ""
            }`}
            onClick={() => setActiveUser(id)}
          >
            <div className="avatar-sm">
              <svg viewBox="0 0 24 24">
                <circle cx="12" cy="8" r="4" />
                <path d="M4 20c0-4 4-6 8-6s8 2 8 6" />
              </svg>
            </div>
            <span>User {id}</span>
          </div>
        ))}
      </aside>

      {/* ===== CHAT WINDOW ===== */}
      <main className="chat-main glass">
        {!activeUser ? (
          <div className="chat-empty">
            <p>Select a chat or message from Feed</p>
          </div>
        ) : (
          <>
            <div className="chat-header">
              Chat with User {activeUser}
            </div>

            <div className="chat-messages">
              {activeMessages.length === 0 ? (
                <p className="empty-text">No messages yet. Say hi 👋</p>
              ) : (
                activeMessages.map((m, i) => (
                  <div
                    key={i}
                    className={`chat-bubble ${
                      m.sender_id === userId ? "sent" : "received"
                    }`}
                  >
                    {m.message_text}
                  </div>
                ))
              )}
            </div>

            {/* INPUT — ALWAYS VISIBLE */}
            <div className="chat-input">
              <input
                placeholder="Type a message..."
                value={text}
                onChange={(e) => setText(e.target.value)}
                onKeyDown={(e) =>
                  e.key === "Enter" && sendMessage()
                }
              />
              <button onClick={sendMessage}>Send</button>
            </div>
          </>
        )}
      </main>
    </div>
  );
}

export default Chat;
